/**
 * Shared meaning of the issue-list filter vocabulary (ADR 0009).
 * The URL codec, the filter schema and the repository all call these helpers
 * so a token like `open` or a calendar date cannot mean two different things.
 */
import {
  CLOSED_ISSUE_STATUSES,
  ISSUE_STATUSES,
  type IssueStatus,
} from "@/types/issue";

export const STATUS_GROUP_OPEN = "open";
export const STATUS_GROUP_CLOSED = "closed";

const CALENDAR_DATE = /^\d{4}-\d{2}-\d{2}$/;

/** Status token the filter vocabulary accepts: a status or a group name. */
export type IssueStatusFilterToken = IssueStatus | "open" | "closed";

export function isIssueStatus(value: string): value is IssueStatus {
  return (ISSUE_STATUSES as readonly string[]).includes(value);
}

/**
 * Expands `open` / `closed` in place. Unknown tokens are dropped. Concrete
 * statuses stay in the order they were written; a group contributes its
 * members in `ISSUE_STATUSES` order, without duplicates.
 */
export function expandStatusFilter(
  values: readonly string[],
): readonly IssueStatus[] {
  const out: IssueStatus[] = [];
  const seen = new Set<IssueStatus>();
  for (const value of values) {
    const members: readonly IssueStatus[] =
      value === STATUS_GROUP_OPEN
        ? ISSUE_STATUSES.filter(
            (status) => !CLOSED_ISSUE_STATUSES.includes(status),
          )
        : value === STATUS_GROUP_CLOSED
          ? CLOSED_ISSUE_STATUSES
          : isIssueStatus(value)
            ? [value]
            : [];
    for (const status of members) {
      if (seen.has(status)) continue;
      seen.add(status);
      out.push(status);
    }
  }
  return out;
}

/**
 * Upper bound for `due_before`. A calendar date includes that whole UTC day
 * (exclusive bound is the next midnight). A timestamp stays strictly before
 * that instant.
 */
export function dueBeforeUpperBound(raw: string): string {
  if (!CALENDAR_DATE.test(raw)) return raw;
  const [year, month, day] = raw.split("-").map((part) => Number(part));
  const next = new Date(Date.UTC(year!, month! - 1, day!));
  next.setUTCDate(next.getUTCDate() + 1);
  return next.toISOString();
}

export function isCalendarDate(value: string): boolean {
  return CALENDAR_DATE.test(value);
}

