/**
 * Filter accepted by the issue repository, service layer and list UI alike.
 * `assigneeId` / `authorId` may be the token `me` until the service resolves
 * it. `dueBefore` is a calendar date or an ISO timestamp. `archivedOnly`
 * lists archived issues and nothing else; `includeArchived` mixes them in.
 */
export interface IssueFilter {
  readonly projectId?: ProjectId;
  readonly status?: readonly IssueStatus[];
  readonly priority?: readonly IssuePriority[];
  readonly assigneeId?: UserId | "me" | null;
  readonly authorId?: UserId | "me";
  readonly labelIds?: readonly LabelId[];
  readonly query?: string;
  readonly dueBefore?: IsoTimestamp | string;
  readonly includeArchived?: boolean;
  readonly archivedOnly?: boolean;
  /** URL vocabulary, accepted alongside the booleans above. */
  readonly archived?: "1" | "only";
}

