export const issueStatusSchema = z.enum([
  "backlog",
  "todo",
  "in_progress",
  "in_review",
  "done",
  "canceled",
]);

/** A status or one of the groups `open` and `closed` (ADR 0009). */
export const issueStatusFilterTokenSchema = z.union([
  issueStatusSchema,
  z.literal("open"),
  z.literal("closed"),
]);

/**
 * Comma-string or array. Unknown tokens fail the schema; the repository
 * still expands group names, so either shape means the same list.
 */
export const issueStatusListSchema = z.preprocess(
  (value) => {
    if (typeof value === "string") {
      return value
        .split(",")
        .map((part) => part.trim())
        .filter((part) => part.length > 0);
    }
    return value;
  },
  z.array(issueStatusFilterTokenSchema).optional(),
);

const calendarDateSchema = z
  .string()
  .regex(/^\d{4}-\d{2}-\d{2}$/, "expected YYYY-MM-DD");

/** Calendar date (whole UTC day) or a full ISO-8601 timestamp. */
export const dueBeforeSchema = z.union([calendarDateSchema, isoTimestampSchema]);

const assigneeFilterSchema = z.union([
  z.literal("me"),
  z.literal("none").transform(() => null),
  userIdSchema,
  z.null(),
]);

const authorFilterSchema = z.union([z.literal("me"), userIdSchema]);

