/** Live rows, live+archived, or archived rows alone. Same predicate for the page and its total. */
function archivePredicate(input: IssueFilterInput): SQL | undefined {
  if (input.archivedOnly === true || input.archived === "only") {
    return isNotNull(issues.archivedAt);
  }
  const include =
    input.includeArchived === true || input.archived === "1";
  const scope: ArchiveScope = shouldFilterArchived({
    includeArchived: include,
  })
    ? {}
    : { includeArchived: true };
  return livePredicate(issues.archivedAt, scope);
}

/** `null` / `none` is unassigned. `undefined` does not filter. `me` matches nothing here — the service resolves it. */
function assigneePredicate(
  assigneeId: IssueFilterInput["assigneeId"],
): SQL | undefined {
  if (assigneeId === undefined) return undefined;
  if (assigneeId === null || assigneeId === "none") {
    return isNull(issues.assigneeId);
  }
  if (assigneeId === "me") return sql`1 = 0`;
  return eq(issues.assigneeId, assigneeId);
}

function authorPredicate(
  authorId: IssueFilterInput["authorId"],
): SQL | undefined {
  if (authorId === undefined) return undefined;
  if (authorId === "me") return sql`1 = 0`;
  return eq(issues.authorId, authorId);
}

/** Every listed label must be present. Any-of is what status and priority do. */
function labelPredicate(
  orgId: OrgId,
  labelIds: readonly LabelId[],
): SQL | undefined {
  if (labelIds.length === 0) return undefined;
  return and(
    ...labelIds.map(
      (labelId) =>
        sql`exists (
          select 1 from ${issueLabels}
          where ${issueLabels.issueId} = ${issues.id}
            and ${issueLabels.orgId} = ${orgId}
            and ${issueLabels.labelId} = ${labelId}
        )`,
    ),
  );
}

/** Builds the shared predicate list behind `listIssues` and its count. */
function issueFilters(input: IssueFilterInput): readonly SQL[] {
  const statuses =
    input.status === undefined ? [] : expandStatusFilter(input.status);

  return compact(
    orgPredicate(issues.orgId, input.orgId),
    archivePredicate(input),
    input.projectId === undefined
      ? undefined
      : eq(issues.projectId, input.projectId),
    statuses.length === 0 ? undefined : inArray(issues.status, [...statuses]),
    input.priority === undefined || input.priority.length === 0
      ? undefined
      : inArray(issues.priority, [...input.priority]),
    assigneePredicate(input.assigneeId),
    authorPredicate(input.authorId),
    input.dueBefore === undefined
      ? undefined
      : and(
          isNotNull(issues.dueAt),
          lt(issues.dueAt, dueBeforeUpperBound(input.dueBefore)),
        ),
    input.query === undefined
      ? undefined
      : or(
          like(issues.title, `%${input.query}%`),
          like(issues.description, `%${input.query}%`),
        ),
    input.labelIds === undefined
      ? undefined
      : labelPredicate(input.orgId, input.labelIds),
  );
}

